tinymce.PluginManager.add("gallery",function(e){
    function openGallery(){
        var file='includes/gallery.php?id=tnmeditor';
      
        var http = new XMLHttpRequest();
        http.open('HEAD', file, false);
        http.send();
        var ans=http.status!=404;
        if(!ans){
           file='../includes/gallery.php?id=tnmeditor'; 
        }

         msgWindow=open(file,window,'scrollbars=yes,resizable=no,width=550,height=400');
         if (msgWindow.opener == null) msgWindow.opener = self;
    }
    function o(){
            e.windowManager.open({
                title:"Image Gallery",
                body:{type:"textbox",
                name:"gallery",
                multiline:!0,
                minWidth:e.getParam("code_dialog_width",600),
                minHeight:e.getParam("code_dialog_height",
                Math.min(tinymce.DOM.getViewPort().h-200,500)),
                value:e.getContent({source_view:!0}),
                spellcheck:!1,style:"direction: ltr; text-align: left"},
    onSubmit:function(o){
        e.focus(),
        e.undoManager.transact(function(){
                e.setContent(o.data.code)}),
                e.focus(),
                e.nodeChanged()
                }
                })}
                e.addCommand("mceCodeEditor",o),
     e.addButton("gallery",{icon:"image",tooltip:"Add From Image Gallery",onclick: openGallery}),
     e.addMenuItem("gallery",{icon:"image",text:"Add From Image Gallery",context:"tools",onclick:o})});
     
     